import secrets

def _t():
    for func in (secrets.token_bytes, secrets.token_hex, secrets.token_urlsafe):
        name = func.__name__
        try:
            func()
        except TypeError:
            raise AssertionError('%s cannot be called with no argument' % name)
        try:
            func(None)
        except TypeError:
            raise AssertionError('%s cannot be called with None' % name)
    size = secrets.DEFAULT_ENTROPY
    assert len(secrets.token_bytes(None)) == size, ('assertEqual', len(secrets.token_bytes(None)), size)
    assert len(secrets.token_hex(None)) == 2 * size, ('assertEqual', len(secrets.token_hex(None)), 2 * size)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

